  "home.cicc.label": { en: "CICC & Licensed RCICs", fr: "CCIC et RCIC agréés", vi: "CICC & RCIC có giấy phép" },
  "home.cicc.title": { en: "Regulated Immigration Consulting", fr: "Consultation en immigration réglementée", vi: "Tư vấn di trú được quản lý" },
  "home.cicc.p1": {
    en: "In Canada, only authorized representatives may provide paid immigration advice. The College of Immigration and Citizenship Consultants (CICC) licenses and regulates Regulated Canadian Immigration Consultants (RCICs) to protect the public.",
    fr: "Au Canada, seuls les représentants autorisés peuvent fournir des conseils en immigration payants. Le Collège des consultants en immigration et en citoyenneté (CCIC) agrée et réglemente les RCIC pour protéger le public.",
    vi: "Tại Canada, chỉ đại diện được ủy quyền mới được cung cấp tư vấn di trú có thu phí. CICC cấp phép và quản lý RCIC để bảo vệ công chúng.",
  },
  "home.cicc.p2": {
    en: "Nuvia Immigration Consulting is led by Thien Pham, RCIC-IRB (R1040752), authorized to represent clients before IRCC and the Immigration and Refugee Board (IRB). Verify any consultant at college-ic.ca.",
    fr: "Nuvia Immigration Consulting est dirigée par Thien Pham, RCIC-IRB (R1040752), autorisé à représenter les clients devant l'IRCC et la CISR. Vérifiez tout consultant sur college-ic.ca.",
    vi: "Nuvia Immigration Consulting do Thien Pham, RCIC-IRB (R1040752) điều hành, được ủy quyền đại diện trước IRCC và IRB. Xác minh tại college-ic.ca.",
  },
  "home.fees.teaser": { en: "View Our Professional Fees", fr: "Voir nos honoraires professionnels", vi: "Xem phí tư vấn chuyên nghiệp" },

