  "contact.gcal.desc": {
    en: "Select a time that works for you. Appointments sync directly with our Google Calendar appointment schedule.",
    fr: "Choisissez un créneau qui vous convient. Les rendez-vous se synchronisent avec notre Google Agenda.",
    vi: "Chọn thời gian phù hợp. Lịch hẹn đồng bộ trực tiếp với Google Calendar của chúng tôi.",
  },
  "contact.gcal.intake": {
    en: "After you select a time, Google Calendar will ask for your contact details, country, service interest, and a brief case summary — all required to complete the booking.",
    fr: "Après avoir choisi un créneau, Google Agenda demandera vos coordonnées, pays, service souhaité et un bref résumé — champs obligatoires pour confirmer la réservation.",
    vi: "Sau khi chọn giờ, Google Calendar sẽ yêu cầu thông tin liên hệ, quốc gia, dịch vụ quan tâm và tóm tắt hồ sơ — tất cả bắt buộc để hoàn tất đặt lịch.",
  },
  "contact.gcal.open": { en: "Open booking page in new tab", fr: "Ouvrir la page de réservation", vi: "Mở trang đặt lịch trong tab mới" },
  "contact.gcal.setup": {
    en: "<strong>Booking calendar setup:</strong> To enable online booking, create a Google Calendar Appointment Schedule with nuvia.immigration@gmail.com, then paste the booking page URL into <code>js/config.js</code> as <code>googleCalendarBookingUrl</code>.<ol><li>Open Google Calendar → Create → Appointment schedule</li><li>Set your availability and consultation duration</li><li>Copy the booking page link from Share → Booking page</li></ol>Until configured, please use WhatsApp, Zalo, email, or the contact form.",
    fr: "<strong>Configuration du calendrier :</strong> Créez un créneau de rendez-vous Google Agenda avec nuvia.immigration@gmail.com, puis collez l'URL dans <code>js/config.js</code>.<ol><li>Google Agenda → Créer → Créneau de rendez-vous</li><li>Définir disponibilités et durée</li><li>Copier le lien de la page de réservation</li></ol>En attendant, utilisez WhatsApp, Zalo, courriel ou le formulaire.",
    vi: "<strong>Cấu hình lịch hẹn:</strong> Tạo Appointment Schedule trên Google Calendar với nuvia.immigration@gmail.com, rồi dán URL vào <code>js/config.js</code>.<ol><li>Google Calendar → Tạo → Lịch hẹn</li><li>Đặt thời gian và thời lượng tư vấn</li><li>Sao chép liên kết trang đặt lịch</li></ol>Tạm thời vui lòng dùng WhatsApp, Zalo, email hoặc biểu mẫu.",
  },
