  "crs.backResources": { en: "← Resources", fr: "← Ressources", vi: "← Tài nguyên" },
  "crs.hero.title": { en: "Express Entry CRS Calculator", fr: "Calculateur CRS Entrée express", vi: "Máy tính CRS Express Entry" },
  "crs.hero.desc": {
    en: "Estimate your CRS score using IRCC factors: age, education, language by skill, work experience, spouse factors, skill transferability, and additional points (no job-offer points). Compare with recent draw cut-offs.",
    fr: "Estimez votre score CRS selon l'IRCC : âge, scolarité, langue par compétence, expérience, conjoint, transfert de compétences et points additionnels (sans emploi réservé). Comparez aux tirages récents.",
    vi: "Ước tính CRS theo IRCC: tuổi, học vấn, ngôn ngữ từng kỹ năng, kinh nghiệm, vợ/chồng, chuyển đổi kỹ năng và điểm bổ sung (không điểm job offer). So với mức cắt rút thăm.",
  },
  "crs.form.title": { en: "Your profile", fr: "Votre profil", vi: "Hồ sơ của bạn" },
